const fs = require('fs');
const readline = require('readline');

async function extract() {
  const fileStream = fs.createReadStream('C:\\Users\\Hype\\.gemini\\antigravity-ide\\brain\\5fee3ef0-37f9-4f31-9d2a-556d5bbd0827\\.system_generated\\logs\\transcript_full.jsonl');
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  for await (const line of rl) {
    if (line.includes('"step_index":483')) {
      const data = JSON.parse(line);
      console.log('Tool calls in 483:', data.tool_calls ? data.tool_calls.map(tc => tc.name) : 'none');
      if (data.tool_calls) {
        fs.writeFileSync('scratch/step_483_tool_calls.json', JSON.stringify(data.tool_calls, null, 2));
        console.log('Wrote scratch/step_483_tool_calls.json');
      }
    }
    // Also let's check step 488 or subsequent steps to see user inputs or diffs
    if (line.includes('"step_index":488') || line.includes('"step_index":487') || line.includes('"step_index":485') || line.includes('"step_index":486')) {
      const data = JSON.parse(line);
      console.log('Step', data.step_index, data.type, (data.content || '').slice(0, 100));
      fs.writeFileSync(`scratch/step_${data.step_index}.json`, JSON.stringify(data, null, 2));
    }
  }
}
extract();
